<?php
declare(strict_types=1);
$user=current_user(); $id=(int)($_GET['id'] ?? 0);
$stmt=db()->prepare("SELECT a.*,u.display_name author_name,c.name category_name,ci.name city_name,ST_Y(a.location) latitude,ST_X(a.location) longitude FROM ads a JOIN users u ON u.user_id=a.author_id JOIN categories c ON c.category_id=a.category_id LEFT JOIN cities ci ON ci.city_id=a.city_id WHERE a.ad_id=:id AND a.status <> 'deleted' LIMIT 1"); $stmt->execute(['id'=>$id]); $ad=$stmt->fetch();
if(!$ad){http_response_code(404);require __DIR__.'/404.php';exit;}
if($ad['status']!=='active' && (!$user || ($user['user_id']!=$ad['author_id'] && $user['role']!=='admin'))){http_response_code(404);require __DIR__.'/404.php';exit;}
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?=e($ad['title'])?></title><link rel="stylesheet" href="../assets/css/auth.css"></head><body><main class="site-shell"><header class="topbar"><a class="brand" href="<?=e(route_url())?>">Доска объявлений</a><nav><a href="<?=e(route_url('ads'))?>">Объявления</a><?php if($user): ?><a href="<?=e(route_url('cabinet'))?>">Кабинет</a><a href="<?=e(route_url('logout'))?>">Выйти</a><?php else: ?><a href="<?=e(route_url('login'))?>">Войти</a><?php endif;?></nav></header><section class="content-card"><span class="eyebrow"><?=e($ad['category_name'])?></span><h1><?=e($ad['title'])?></h1><p><?=nl2br(e($ad['description']))?></p><strong class="price"><?=e((string)$ad['price'])?> ₽</strong><div class="profile-grid"><p><b>Город:</b> <?=e($ad['city_name']??'Не указан')?></p><p><b>Автор:</b> <?=e($ad['author_name'])?></p><p><b>Статус:</b> <?=e($ad['status'])?></p><p><b>Координаты:</b> <?=e((string)$ad['latitude'])?>, <?=e((string)$ad['longitude'])?></p></div><?php if($user && ($user['user_id']==$ad['author_id'] || $user['role']==='admin')): ?><div class="actions"><a class="button" href="<?=e(route_url('ads/edit'))?>?id=<?=(int)$ad['ad_id']?>">Редактировать</a></div><?php endif;?></section></main></body></html>